const CHANNAPATNA_INFO={id:"channapatna-toys",title:"Channapatna Toys — Karnataka's Lacquerware Craft",originRegion:"Channapatna, Ramanagara District, Karnataka",eraOrigin:"18th Century (Tipu Sultan's Patronage)",giTagStatus:"Geographical Indication (GI) Certified — Channapatna Toys & Dolls (2005)",quickStats:[{label:"Birthplace",value:"Channapatna, Karnataka",icon:"📍"},{label:"GI Tagged",value:"Channapatna Toys & Dolls (2005)",icon:"🏷️"},{label:"Wood Used",value:"Ivory Wood (Aale Mara)",icon:"🪵"},{label:"Finish",value:"Natural Lacquer (Lac Resin)",icon:"✨"},{label:"Technique",value:"Bow-Lathe Turnery",icon:"🛠️"},{label:"Nickname",value:"'Gombegala Ooru' — City of Toys",icon:"🎠"}]},HISTORY_CHAPTERS=[{title:"The City of Toys",period:"Channapatna, Karnataka",description:"Sixty kilometres from Bengaluru, the town of Channapatna in Ramanagara district is lovingly called 'Gombegala Ooru' — the City of Toys — and is today the heart of India's wooden-toy tradition."},{title:"Tipu Sultan's Patronage",period:"18th Century",description:"Legend holds that the Tiger of Mysore, Tipu Sultan, invited Persian artisans to Channapatna to teach the region's craftsmen the art of lacquerware — a cross-cultural spark that shaped the craft's signature glossy finish."},{title:"The Lac-Turnery Craft",period:"Generational",description:"The technique — turning soft ivory wood on a bow-powered lathe and sealing it with molten natural lac — passed down through artisan families of Channapatna and its surrounding villages."},{title:"GI Recognition",period:"2005 – 2006",description:"'Channapatna Toys and Dolls' earned the Geographical Indication tag, legally protecting the craft's identity and the livelihoods of the town's toymakers."},{title:"Organic Revival",period:"Present Day",description:"Modern workshops blend tradition with child-safety: natural vegetable and food-grade dyes, non-toxic lac, and export to more than twenty countries worldwide."}],CRAFTING_PROCESS=[{step:1,title:"Seasoning the Wood",description:"Logs of aale mara (ivory wood, Wrightia tinctoria) are felled and dried in the sun for months until light, stable and ready for the lathe."},{step:2,title:"Turning on the Bow Lathe",description:"The artisan spins the wooden blank with a traditional bow-string lathe, controlling speed with a treadle while shaping the toy."},{step:3,title:"Smoothing & Shaping",description:"Sharp chisels carve the rotating wood into elephants, bells, tops and dolls — each contour cut freehand."},{step:4,title:"Applying the Lacquer",description:"Sticks of natural lac resin are pressed against the spinning toy; the friction heat melts the lac and fuses it evenly onto the wood."},{step:5,title:"Hand Painting & Detailing",description:"Fine lines, eyes and patterns are painted by hand — often by women artisans — using natural and food-grade dyes."},{step:6,title:"Polishing & Inspection",description:"Each toy is polished to a soft sheen and inspected for safety, ensuring every piece is smooth, non-toxic and child-friendly."}],SUSTAINABLE_MATERIALS=[{name:"Ivory Wood (Aale Mara)",description:"Wrightia tinctoria is a fast-growing local timber — light, fine-grained and sustainably harvested from Karnataka's woodlands.",icon:"🪵"},{name:"Natural Lac Resin",description:"The glossy finish comes from lac, a natural resin secreted by the lac insect — biodegradable and completely non-toxic.",icon:"🐛"},{name:"Vegetable & Food-Grade Dyes",description:"Colours are drawn from turmeric, indigo, kumkuma and other natural sources, keeping the toys safe for babies to handle.",icon:"🌿"},{name:"No Plastic, No Toxins",description:"Every Channapatna toy is free of plastic, synthetic paints and sharp edges — renewable, biodegradable play that lasts generations.",icon:"♻️"}],TRADITIONAL_DESIGNS=[{name:"The Channapatna Elephant",description:"The iconic red-and-gold lacquered elephant, stacked in graded sizes — the postcard of the craft.",icon:"🐘"},{name:"Buguri (Spinning Top)",description:"The classic lattoo, spun on floors across Indian childhoods, painted in bold bands of lacquer.",icon:"🪀"},{name:"Gilike (Rattle Bell)",description:"A little bell with a wooden handle and beads — the first toy of countless infants.",icon:"🔔"},{name:"Miniature Kitchen Sets",description:"Play kitchens, utensils and fruit that taught generations of children household rhythms.",icon:"🍽️"},{name:"Bangles & Ornaments",description:"Lacquered bangles and jewellery echoing the same warm, glossy palette of the toys.",icon:"📿"},{name:"Toy Trains & Rattles",description:"Modern classics — trains, cars and rattles — reinterpreted in traditional ivory-wood lacquer.",icon:"🚂"}],ARTISAN_COMMUNITY={title:"The Toymakers of Gombegala Ooru",description:"Thousands of artisans — men at the lathes and women at the paintbrushes — carry the craft across Channapatna town and its villages. Organised under bodies like the Channapatna Toys Manufacturers' Association, they have turned a centuries-old skill into a sustainable rural industry, exporting handmade, eco-friendly toys to homes around the world."},GALLERY_IMAGES=[{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Channapatna-toys.jpg",caption:"Classic Channapatna toys — elephants, bells and doll sets in the craft's warm lacquer palette.",category:"Classic"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Channapatna_artist_making_toy.jpg",caption:"An artisan shaping a toy on the traditional bow-powered lathe.",category:"Crafting"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Channapatna_artist_coloring_toy.jpg",caption:"Hand colouring a lacquered toy — fine detailing done by artisans, many of them women.",category:"Crafting"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Finished_Channapatna_toys.jpg",caption:"Finished Channapatna toys ready for market — glossy, seamless and child-safe.",category:"Classic"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Toy_flute_from_Channapatna,_Karnataka,_India.jpg",caption:"A traditional toy flute from Channapatna — musical play in ivory wood and lacquer.",category:"Designs"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Channapatna_Bangles_(4784914041).jpg",caption:"Lacquered bangles among Channapatna toys — the glossy finish that crowns the craft.",category:"Designs"}],REFERENCES=[{text:"Geographical Indications Registry — Channapatna Toys and Dolls (GI certified).",link:"https://ipindia.gov.in"},{text:"Office of the Development Commissioner (Handicrafts) — Channapatna wooden toys.",link:"https://handicrafts.nic.in"},{text:"Karnataka Handicrafts Development Corporation (KHDC) — Channapatna toys.",link:"https://karnatakahandicrafts.com"},{text:"Sahapedia — The lacquerware toys of Channapatna.",link:"https://www.sahapedia.org/channapatna-toys"}];"undefined"!=typeof module&&module.exports&&(module.exports={CHANNAPATNA_INFO:CHANNAPATNA_INFO,HISTORY_CHAPTERS:HISTORY_CHAPTERS,CRAFTING_PROCESS:CRAFTING_PROCESS,SUSTAINABLE_MATERIALS:SUSTAINABLE_MATERIALS,TRADITIONAL_DESIGNS:TRADITIONAL_DESIGNS,ARTISAN_COMMUNITY:ARTISAN_COMMUNITY,GALLERY_IMAGES:GALLERY_IMAGES,REFERENCES:REFERENCES});